try {
  const stateData = this.#currentSubview.captureState?.();
  await this.#handleForwardAction(this.#currentState, stateData);
} catch (error) {
  this.#currentSubview.showNotification({
    title: error.title || error.message,
    description: error.text,
    error,
    type: "error",
  });
}
